function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function request(body,code=session?.code,token=session?.token){
 const generation=accountGeneration;
 const response=await fetch(body?'/api':`/api?code=${encodeURIComponent(code||'health')}`,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},body:body?JSON.stringify({...body,requestId:body.requestId||crypto.randomUUID()}):undefined,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});
 let data;try{data=await response.json();}catch{throw new Error('Không kết nối được máy chủ.');}if(code!=='health'&&generation!==accountGeneration)throw new Error('Phiên tài khoản đã thay đổi.');if(!response.ok)throw new Error(data.error||'Không thực hiện được yêu cầu.');return data;
}
function applyAccount(value){if(account?.id===value.id&&(value.version||0)<(account.version||0))return;const changed=account?.id!==value.id;account=value;if(document.documentElement){document.documentElement.dataset.cardSkin=value.equippedCardSkin||'classic';document.documentElement.dataset.chipSkin=value.equippedChipSkin||'classic';}selectedCharacter=value.equippedSkin;unlockedCharacters=value.ownedSkins;profile=value.name||value.username;if(changed){accountGeneration++;sessions=read('bella.sessions.'+value.id,{});session=null;room=null;page='home';}}
async function refreshWallet(){const data=await request(null,'account',null);applyAccount(data.account);render();}
function accept(data){if(data.account)applyAccount(data.account);if(data.token){session={code:data.room.code,token:data.token};sessions[session.code]=session;save();}const previous=room?.version;queueTableEffects(room,data.room);chipMoments(room,data.room);room=data.room;clockOffset=room.serverNow-Date.now();online=true;if(previous!==room.version||page==='home')render();else patchDraft();updateClocks();syncPeek();syncReactionTimers();const reward=room.coinReward,key=room.code+':'+room.startedAt;const mine=room.players.find(p=>p.accountId===account?.id),group=groupRewardText(room.groupReward?.[mine?.id]);
 if((reward?.amount&&room.players.find(p=>p.id===reward.playerId)?.accountId===account?.id||group)&&lastWalletTour!==key){lastWalletTour=key;const win=reward?.amount&&reward.playerId===mine?.id?'Vô địch '+reward.entrants+' người: +'+number(reward.amount)+' coin! ':'';refreshWallet().then(()=>toast(win+(group||''))).catch(()=>{});}}

async function send(body){if(busy)return;busy=true;render();try{const data=await request({...body,code:session.code});accept(data);}catch(e){toast(e.message);}finally{busy=false;render();}}

// Full screen: Android/desktop browsers can do it from a tap; iPhone Safari cannot, so iPhone players are told to
// add the game to the Home Screen, where it opens without any browser bars (see manifest.webmanifest).
const standalone=()=>matchMedia('(display-mode: fullscreen), (display-mode: standalone)').matches||navigator.standalone===true;
document.addEventListener('click',e=>{if(e.target.closest('[data-missions]'))openMissions(account);});
document.addEventListener('click',e=>{if(!e.target.closest('[data-fullscreen]'))return;
 const el=document.documentElement;
 if(document.fullscreenElement){document.exitFullscreen?.();return;}
 if(el.requestFullscreen){el.requestFullscreen({navigationUI:'hide'}).then(()=>screen.orientation?.lock?.(innerWidth>innerHeight?'landscape':'portrait')).catch(()=>{});return;}
 toast('iPhone: bấm nút Chia sẻ ⬆ rồi chọn “Thêm vào MH chính”. Mở Bella từ biểu tượng đó để chơi toàn màn hình.');
});
