configureCardSkins({getAccount:()=>account,request:async body=>{const data=await request(body,null,null);applyAccount(data.account);render();return data;}});
configureAccountName({getAccount:()=>account,request:async body=>{const data=await request(body,null,null);applyAccount(data.account);render();toast('Đã đổi tên thành '+data.account.name);if(session)request(null,session.code,session.token).then(accept).catch(()=>{});return data;}});
